// v23.xx (gfx21), HIS ORDER (2026-10-12) on the graphics program, item 4 (second half): A HURT MACHINE SPARKS, SMOKES AND BURNS.
// The plates (gfx20) say how hurt a machine is up close; this says it from across the room. Under half health a machine throws a
// short burst of sparks every 0.3 to 0.9 seconds. Under a quarter it also burns: flames lick over its body (drawn bright, and lent
// to the bloom through gfxEmit) and a column of dark smoke climbs off it and drifts, each puff a baked soft sprite stamped with
// drawImage (one sprite for every puff, RSMOKE capped at 160, about 35 a machine). Everything follows the mirrored health and the
// raid clock, so a linked window sees the same; the state lives in a WeakMap on the drawing side (GFXDMGS), never on the machine.
// Effects REDUCED halves the smoke. Puffs, sparks and flicker draw on the cosmetic stream (fxn) or the clock, never the raid
// stream: the seed is untouched, and nothing a fight reads.
var RSMOKE=[], GFXDMGS=(typeof WeakMap==='function')?new WeakMap():null;
function gfxSmokeSpr(){
  var s=gfxStore('smoke'), c, x, gr;
  if(s.m.spr) return s.m.spr;
  c=document.createElement('canvas'); c.width=64; c.height=64; x=c.getContext('2d'); if(!x) return null;
  gr=x.createRadialGradient(32,32,2,32,32,31);
  gr.addColorStop(0,'rgba(52,54,57,0.95)'); gr.addColorStop(0.5,'rgba(44,46,49,0.6)'); gr.addColorStop(1,'rgba(38,40,43,0)');
  x.fillStyle=gr; x.fillRect(0,0,64,64);
  s.m.spr=c; s.n=1; return c;
}
function gfxMachTop(e){ var P=(typeof GFXPLATE!=='undefined')?GFXPLATE[e.kind]:null, r=e.r||14; return P?P[1]*r:r*1.5; }
function gfxDmgFx(e){
  var f, s, t, dt, r, top, rate, n, i, k, j, x0, y0, h, w, fl;
  if(!e||!(e.maxhp>0)||!(e.hp>0)||GFX.bypass||typeof G==='undefined'||!G||G.sim) return 0;
  f=e.hp/e.maxhp; if(f>=0.5) return 0;
  t=G.t||0; s=GFXDMGS?GFXDMGS.get(e):null;
  if(!s){ s={t:t,sp:t+fxn(0.05,0.4),acc:0}; if(GFXDMGS) GFXDMGS.set(e,s); }
  dt=Math.max(0,Math.min(0.1,t-s.t)); s.t=t; r=e.r||14; top=gfxMachTop(e);
  if(t>=s.sp){ s.sp=t+fxn(0.3,0.9); spark(e.x+fxn(-0.45,0.45)*r,e.y-top*0.55+9,(f<0.25)?'#ffb05a':'#ffe08a',4,150); }
  if(f>=0.25) return 1;
  rate=(f<0.12?10:8)*((CFG.fxLevel===0)?0.5:1); s.acc+=dt*rate; n=Math.floor(s.acc); s.acc-=n;
  for(i=0;i<n;i++){
    if(RSMOKE.length>=160) RSMOKE.shift();
    RSMOKE.push({x:e.x+fxn(-0.3,0.3)*r,y:e.y,z:top*0.7,t0:t,life:fxn(2.5,3.5),vx:fxn(-4,4)+6,vz:fxn(16,26),s:fxn(0.8,1.2)*r*0.42});
  }
  // the fire: three flame tongues over the hull, flickering on the clock (entT keeps them still through a hit pause)
  k=(typeof entT==='function')?entT(e):t; y0=e.y-top*0.45;
  wc.save(); wc.globalCompositeOperation='lighter';
  for(j=0;j<3;j++){
    fl=0.55+0.25*Math.sin(k*17+j*2.1)+0.2*Math.sin(k*29.3+j*4.7);
    h=r*(0.42+0.3*fl); w=r*(0.16+0.04*Math.sin(k*11+j)); x0=e.x+(j-1)*r*0.26;
    wc.fillStyle='rgba(255,120,36,0.55)';
    wc.beginPath(); wc.moveTo(x0-w,y0); wc.quadraticCurveTo(x0-w*0.6,y0-h*0.6,x0+Math.sin(k*9+j)*w*0.5,y0-h); wc.quadraticCurveTo(x0+w*0.6,y0-h*0.6,x0+w,y0); wc.closePath(); wc.fill();
    wc.fillStyle='rgba(255,214,120,0.6)';
    wc.beginPath(); wc.moveTo(x0-w*0.45,y0); wc.quadraticCurveTo(x0,y0-h*0.75,x0+w*0.45,y0); wc.closePath(); wc.fill();
  }
  wc.restore();
  try{ gfxEmit(e.x,y0-r*0.3,r*1.6,'#ff8a3a',0.6); }catch(_ge){}
  return 2;
}
function gfxSmokeDraw(){
  var i, p, t, a, sz, spr, n=0, ga;
  if(!RSMOKE.length||typeof G==='undefined'||!G) return 0;
  spr=gfxSmokeSpr(); if(!spr) return 0;
  ga=wc.globalAlpha;
  for(i=RSMOKE.length-1;i>=0;i--){
    p=RSMOKE[i]; t=(G.t||0)-p.t0;
    if(t<0||t>p.life){ RSMOKE.splice(i,1); continue; }
    a=Math.min(1,t/0.3)*(1-t/p.life); sz=p.s*(1+t*0.9);
    wc.globalAlpha=a*0.8;
    wc.drawImage(spr,p.x+p.vx*t-sz,p.y-p.z-p.vz*t-sz,sz*2,sz*2); n++;
  }
  wc.globalAlpha=ga;
  return n;
}
var HITSIL=null, GFX_NOSHAD=0;

